    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: A 2-year-old child presents with a barking cough, inspiratory stridor, and low-grade fever. What is the most common causative agent?', '["Respiratory Syncytial Virus (RSV)", "Parainfluenza virus type 1", "Haemophilus influenzae type b", "Staphylococcus aureus"]', 1, 'Parainfluenza virus is the most common cause of croup (Laryngotracheobronchitis). (Nelson)'),
    (v_topic_id, '2: A 3-year-old presents with acute onset of high fever, drooling, and a tripod position. What is the immediate next step in management?', '["Perform a lateral neck X-ray", "Visual examination of the throat with a tongue depressor", "Maintain a calm environment and prepare for urgent airway management", "Administer nebulized epinephrine"]', 2, 'Epiglottitis is a medical emergency; any agitation or throat examination can trigger complete airway obstruction. (Harriet Lane)'),
    (v_topic_id, '3: Which of the following is the characteristic X-ray finding in a child with Epiglottitis?', '["Steeple sign", "Thumbprint sign", "Sail sign", "Boot-shaped heart"]', 1, 'The thumbprint sign represents a swollen epiglottis on a lateral neck radiograph. (Case Files)'),
    (v_topic_id, '4: A 6-month-old infant presents with rhinorrhea, cough, and wheezing. Physical exam reveals tachypnea and intercostal retractions. What is the most likely diagnosis?', '["Pneumonia", "Bronchiolitis", "Asthma", "Croup"]', 1, 'Bronchiolitis is the most common lower respiratory tract infection in infants, typically caused by RSV. (Nelson)'),
    (v_topic_id, '5: What is the primary treatment for an infant with moderate bronchiolitis?', '["Albuterol nebulization", "Corticosteroids", "Supportive care (hydration and nasal suctioning)", "Intravenous antibiotics"]', 2, 'Mainstay of treatment for bronchiolitis is supportive care; bronchodilators and steroids are generally not recommended. (AAP Guidelines)'),
    (v_topic_id, '6: A 5-year-old presents with fever, sore throat, and a "sandpaper" rash that started on the neck and spread to the trunk. What is the most likely organism?', '["Staphylococcus aureus", "Group A Streptococcus", "Mycoplasma pneumoniae", "Epstein-Barr Virus"]', 1, 'Scarlet fever is caused by erythrogenic toxin-producing Group A Strep. (Case Files)'),
    (v_topic_id, '7: A child with Group A Streptococcal pharyngitis is at risk for which non-suppurative complication if left untreated?', '["Post-streptococcal glomerulonephritis", "Acute Rheumatic Fever", "Both A and B", "Neither A nor B"]', 2, 'Antibiotics prevent Acute Rheumatic Fever but do not necessarily prevent PSGN. (Nelson)'),
    (v_topic_id, '8: A 15-year-old adolescent presents with fever, exudative pharyngitis, and posterior cervical lymphadenopathy. A Monospot test is positive. What complication should be monitored for?', '["Splenic rupture", "Aortic aneurysm", "Liver failure", "Renal failure"]', 0, 'Infectious mononucleosis (EBV) often involves splenomegaly, risking rupture with trauma. (Harriet Lane)'),
    (v_topic_id, '9: Which of the following physical exam findings is most suggestive of Pertussis in a 2-month-old infant?', '["Classic ''whoop''", "Post-tussive emesis", "Inspiratory stridor", "High fever"]', 1, 'Infants often lack the "whoop" but frequently have post-tussive emesis or apnea. (Case Files)'),
    (v_topic_id, '10: What is the drug of choice for treating a child with Bordetella pertussis and their close contacts?', '["Amoxicillin", "Azithromycin", "Ceftriaxone", "Ciprofloxacin"]', 1, 'Macrolides are first-line for treatment and post-exposure prophylaxis of Pertussis. (Nelson)'),
    (v_topic_id, '11: A 10-year-old child presents with a "slapped cheek" rash and a reticular, lace-like rash on the extremities. What is the causative agent?', '["Human Herpesvirus 6", "Parvovirus B19", "Rubella virus", "Measles virus"]', 1, 'Parvovirus B19 causes Erythema Infectiosum (Fifth Disease). (Nelson)'),
    (v_topic_id, '12: A child with Parvovirus B19 infection and underlying sickle cell disease is at risk for which life-threatening condition?', '["Aplastic crisis", "Splenic sequestration", "Vaso-occlusive crisis", "Hyperhemolytic crisis"]', 0, 'Parvovirus B19 infects erythroid progenitor cells, leading to transient cessation of RBC production. (Case Files)'),
    (v_topic_id, '13: High fever for 3-4 days followed by the sudden appearance of a rose-colored maculopapular rash as the fever breaks is characteristic of:', '["Roseola Infantum (HHV-6)", "Measles", "Rubella", "Varicella"]', 0, 'Roseola (Exanthema Subitum) is classic for high fever followed by rash after defervescence. (Nelson)'),
    (v_topic_id, '14: Which of the following is a pathognomonic sign of Measles (Rubeola)?', '["Forchheimer spots", "Koplik spots", "Pastia lines", "Nagayama spots"]', 1, 'Koplik spots are small white spots on the buccal mucosa. (Nelson)'),
    (v_topic_id, '15: A 4-year-old child presents with fever, cough, coryza, and conjunctivitis followed by a cephalocaudal rash. Which supplement is shown to reduce morbidity and mortality in Measles?', '["Vitamin C", "Vitamin A", "Zinc", "Vitamin D"]', 1, 'Vitamin A deficiency is associated with severe measles; supplementation is recommended for all children. (WHO)'),
    (v_topic_id, '16: A child presents with tender swelling of the parotid glands. What is the most common complication of this infection in post-pubertal males?', '["Pancreatitis", "Orchitis", "Meningitis", "Oophoritis"]', 1, 'Mumps-associated orchitis can occur in up to 30% of post-pubertal males. (Nelson)'),
    (v_topic_id, '17: A child presents with dewdrop-on-a-rosepetal vesicles in various stages of evolution. What is the most common secondary bacterial infection associated with this condition?', '["Group A Streptococcus", "Staphylococcus aureus", "Both A and B", "Pseudomonas aeruginosa"]', 2, 'Staph and Strep are common causes of secondary skin infections in Varicella. (Case Files)'),
    (v_topic_id, '18: What is the first-line treatment for a child with uncomplicated acute otitis media?', '["Ceftriaxone", "High-dose Amoxicillin", "Azithromycin", "Ciprofloxacin ear drops"]', 1, 'High-dose Amoxicillin (80-90 mg/kg/day) is first-line for AOM. (AAP)'),
    (v_topic_id, '19: A child presents with persistent ear pain, fever, and protrusion of the auricle. What is the most likely complication?', '["Mastoiditis", "Cholesteatoma", "Tympanosclerosis", "Labyrinthitis"]', 0, 'Acute mastoiditis is a clinical diagnosis characterized by posterior ear pain and displaced auricle. (Harriet Lane)'),
    (v_topic_id, '20: What is the most common bacterial cause of pediatric pneumonia in children older than 5 years?', '["Streptococcus pneumoniae", "Mycoplasma pneumoniae", "Staphylococcus aureus", "Group B Streptococcus"]', 1, 'Atypical pathogens like Mycoplasma become more common in school-aged children. (Nelson)'),
    (v_topic_id, '21: A child presents with high fever, productive cough, and lobar consolidation on chest X-ray. What is the most likely organism?', '["Mycoplasma pneumoniae", "Streptococcus pneumoniae", "Chlamydia trachomatis", "Respiratory Syncytial Virus"]', 1, 'S. pneumoniae is the most common cause of bacterial lobar pneumonia across all ages. (Case Files)'),
    (v_topic_id, '22: An 8-year-old presents with a "walking pneumonia" pattern (interstitial infiltrates, non-productive cough). What is the appropriate treatment?', '["Amoxicillin", "Azithromycin", "Ceftriaxone", "Vancomycin"]', 1, 'Macrolides are the treatment of choice for Mycoplasma (atypical) pneumonia. (Nelson)'),
    (v_topic_id, '23: What is the most common cause of neonatal sepsis and meningitis?', '["Escherichia coli", "Group B Streptococcus (GBS)", "Listeria monocytogenes", "Staphylococcus epidermidis"]', 1, 'GBS is the leading cause of early-onset neonatal sepsis. (Harriet Lane)'),
    (v_topic_id, '24: A 2-year-old presents with fever, irritability, and a bulging fontanelle. CSF analysis shows high protein, low glucose, and high WBC count with neutrophil predominance. What is the likely diagnosis?', '["Viral meningitis", "Bacterial meningitis", "Fungal meningitis", "Tuberculous meningitis"]', 1, 'Neutrophil predominance and low glucose are classic for bacterial meningitis. (Nelson)'),
    (v_topic_id, '25: What is the most common cause of viral meningitis in children?', '["Herpes Simplex Virus", "Enteroviruses (e.g., Coxsackievirus)", "Mumps virus", "Varicella Zoster Virus"]', 1, 'Enteroviruses account for the majority of viral (aseptic) meningitis cases. (Case Files)'),
    (v_topic_id, '26: A child presents with multiple painful vesicles and ulcers on the anterior tongue and buccal mucosa, accompanied by high fever and refusal to eat. Diagnosis?', '["Herpangina", "Herpetic gingivostomatitis", "Hand-foot-mouth disease", "Aphthous ulcers"]', 1, 'Herpetic gingivostomatitis involves the anterior oral cavity; herpangina is usually posterior. (Nelson)'),
    (v_topic_id, '27: A child presents with vesicles on the soft palate and uvula, but none on the front of the mouth. This is most likely:', '["Herpetic gingivostomatitis", "Herpangina (Coxsackie A)", "Measles", "Roseola"]', 1, 'Herpangina is caused by Coxsackie virus and typically involves the posterior pharynx. (Case Files)'),
    (v_topic_id, '28: What is the most common cause of urinary tract infections (UTI) in children?', '["Proteus mirabilis", "Escherichia coli", "Klebsiella pneumoniae", "Staphylococcus saprophyticus"]', 1, 'E. coli causes over 80% of pediatric UTIs. (Harriet Lane)'),
    (v_topic_id, '29: A 12-month-old female presents with unexplained fever. What is the preferred method for obtaining a urine culture?', '["Bag specimen", "Clean catch", "Bladder catheterization", "Suprapubic aspiration"]', 2, 'Catheterization is preferred in non-toilet trained children to avoid contamination. (AAP)'),
    (v_topic_id, '30: What is the most common cause of viral gastroenteritis in children worldwide?', '["Norovirus", "Rotavirus", "Adenovirus", "Astrovirus"]', 1, 'Rotavirus was historically the most common, though Norovirus is increasingly prevalent where Rotavirus vaccination is high. (Nelson)'),
    (v_topic_id, '31: A 2-year-old child presents with 2 days of watery diarrhea, vomiting, and mild dehydration. What is the most appropriate initial management?', '["Intravenous fluids", "Oral rehydration therapy (ORT)", "Antidiarrheal medications", "Empiric antibiotics"]', 1, 'ORT is the first-line treatment for mild to moderate dehydration. (Nelson)'),
    (v_topic_id, '32: A child presents with bloody diarrhea and abdominal cramps after eating an undercooked hamburger. What complication should you be concerned about?', '["Hemolytic Uremic Syndrome (HUS)", "Intussusception", "Toxic megacolon", "Appendicitis"]', 0, 'E. coli O157:H7 (EHEC) is associated with HUS. (Case Files)'),
    (v_topic_id, '33: What is the triad of Hemolytic Uremic Syndrome (HUS)?', '["Fever, Rash, Arthralgia", "Microangiopathic hemolytic anemia, Thrombocytopenia, Acute Renal Failure", "Jaundice, Splenomegaly, Anemia", "Proteinuria, Hematuria, Edema"]', 1, 'HUS triad includes anemia, low platelets, and kidney injury. (Nelson)'),
    (v_topic_id, '34: A child presents with high fever, headache, and a rapidly progressing petechial/purpuric rash. What is the most likely organism?', '["Streptococcus pneumoniae", "Neisseria meningitidis", "Haemophilus influenzae", "Borrelia burgdorferi"]', 1, 'Meningococcemia is characterized by rapid progression and purpuric lesions (purpura fulminans). (Harriet Lane)'),
    (v_topic_id, '35: What is the treatment of choice for a child with Osteomyelitis, assuming the most common organism?', '["Vancomycin or Nafcillin/Cefazolin", "Ceftriaxone", "Ciprofloxacin", "Metronidazole"]', 0, 'S. aureus is the most common cause; treatment targets methicillin-sensitive or resistant strains. (Case Files)'),
    (v_topic_id, '36: A child with sickle cell disease presents with fever and bone pain. What additional organism should be covered in the treatment of osteomyelitis?', '["Pseudomonas aeruginosa", "Salmonella species", "Listeria monocytogenes", "Streptococcus pyogenes"]', 1, 'Salmonella is a unique cause of osteomyelitis in sickle cell patients. (Nelson)'),
    (v_topic_id, '37: What is the most common cause of septic arthritis in children?', '["Kingella kingae", "Staphylococcus aureus", "Neisseria gonorrhoeae", "Streptococcus pneumoniae"]', 1, 'S. aureus is the leading cause across most age groups. (Harriet Lane)'),
    (v_topic_id, '38: A 4-year-old child presents with a limp and fever. Joint aspiration shows a WBC count of 80,000 with 90% neutrophils. Diagnosis?', '["Transient synovitis", "Septic arthritis", "Juvenile Idiopathic Arthritis", "Osgood-Schlatter disease"]', 1, 'Joint WBC >50,000 is highly suggestive of septic arthritis. (Case Files)'),
    (v_topic_id, '39: A child presents with honey-colored crusts on the face. What is the most likely diagnosis and treatment?', '["Cellulitis; Cephalexin", "Impetigo; Topical Mupirocin", "Eczema; Hydrocortisone", "Erysipelas; Penicillin"]', 1, 'Impetigo is superficial and usually treated topically if localized. (Nelson)'),
    (v_topic_id, '40: What is the most common cause of orbital cellulitis in children?', '["Insect bites", "Sinusitis", "Dental infection", "Trauma"]', 1, 'Ethmoid sinusitis is the most common source of infection spreading to the orbit. (Case Files)'),
    (v_topic_id, '41: Differentiating orbital cellulitis from preseptal cellulitis is best done by checking for:', '["Fever", "Eyelid swelling", "Pain with eye movement or proptosis", "Redness of the eyelid"]', 2, 'Orbital cellulitis involves deep structures, causing ophthalmoplegia and proptosis. (Nelson)'),
    (v_topic_id, '42: A child presents with fever and a "bulls-eye" (erythema migrans) rash after a camping trip in the Northeast US. Treatment?', '["Amoxicillin (if <8 years old)", "Doxycycline (if <8 years old)", "Azithromycin", "Ceftriaxone"]', 0, 'Amoxicillin is preferred for Lyme disease in children <8 years old due to potential tooth staining with Doxycycline. (AAP)'),
    (v_topic_id, '43: A child presents with fever and a petechial rash that started on the wrists and ankles and moved centrally. What is the most likely diagnosis?', '["Meningococcemia", "Rocky Mountain Spotted Fever (RMSF)", "Measles", "Syphilis"]', 1, 'RMSF rash classically starts on the extremities and moves inward. (Case Files)'),
    (v_topic_id, '44: What is the recommended treatment for Rocky Mountain Spotted Fever in children of any age?', '["Amoxicillin", "Doxycycline", "Chloramphenicol", "Ceftriaxone"]', 1, 'Doxycycline is the drug of choice for RMSF regardless of age due to the severity of the disease. (CDC)'),
    (v_topic_id, '45: A child presents with persistent fever for 5 days, bilateral conjunctival injection, "strawberry tongue", and swelling of the hands and feet. Diagnosis?', '["Scarlet fever", "Kawasaki disease", "Infectious mononucleosis", "Toxic Shock Syndrome"]', 1, 'Kawasaki disease is a medium-vessel vasculitis. (Nelson)'),
    (v_topic_id, '46: What is the primary treatment for Kawasaki disease to prevent coronary artery aneurysms?', '["Aspirin and Intravenous Immunoglobulin (IVIG)", "Corticosteroids", "Antibiotics", "Aspirin only"]', 0, 'IVIG significantly reduces the risk of coronary complications. (Harriet Lane)'),
    (v_topic_id, '47: A 2-year-old child presents with a "slapped cheek" rash. The mother is pregnant. What is the major risk to the fetus?', '["Congenital heart disease", "Hydrops fetalis", "Microcephaly", "Cleft palate"]', 1, 'Parvovirus B19 infection in pregnancy can cause fetal anemia and hydrops. (Case Files)'),
    (v_topic_id, '48: Cat-scratch disease is caused by which organism?', '["Pasteurella multocida", "Bartonella henselae", "Toxoplasma gondii", "Francisella tularensis"]', 1, 'Bartonella henselae is transmitted by cats and causes regional lymphadenopathy. (Nelson)'),
    (v_topic_id, '49: What is the characteristic finding of Pinworm (Enterobius vermicularis) infection?', '["Bloody diarrhea", "Nocturnal perianal pruritus", "Abdominal pain", "Weight loss"]', 1, 'Female worms migrate to the perianal area at night to lay eggs. (Harriet Lane)'),
    (v_topic_id, '50: A child presents with an itchy scalp and small white nits attached to the hair shafts. Treatment?', '["Oral Griseofulvin", "Topical Permethrin", "Topical Ketoconazole", "Oral Amoxicillin"]', 1, 'Permethrin is first-line for Pediculosis capitis (head lice). (Nelson)'),
    (v_topic_id, '51: A 10-year-old presents with a ring-shaped, scaly, pruritic rash with central clearing on the arm. Diagnosis?', '["Tinea corporis", "Psoriasis", "Nummular eczema", "Granuloma annulare"]', 0, 'Tinea corporis (ringworm) is a fungal infection of the skin. (Case Files)'),
    (v_topic_id, '52: What is the treatment of choice for Tinea capitis (fungal infection of the scalp)?', '["Topical Clotrimazole", "Oral Griseofulvin", "Oral Amoxicillin", "Topical Hydrocortisone"]', 1, 'Tinea capitis requires systemic antifungal therapy as topicals do not penetrate the hair follicle. (Nelson)'),
    (v_topic_id, '53: A child presents with a round, bald patch on the scalp with "black dots" (broken hairs). This is characteristic of:', '["Alopecia areata", "Tinea capitis", "Trichotillomania", "Traction alopecia"]', 1, 'The "black dot" sign is classic for tinea capitis. (Harriet Lane)'),
    (v_topic_id, '54: A child with fever and ear pain has a bulging, erythematous, immobile tympanic membrane. This is:', '["Otitis externa", "Acute otitis media", "Otitis media with effusion", "Myringosclerosis"]', 1, 'Immobility and bulging are key signs of acute infection. (AAP)'),
    (v_topic_id, '55: A child presents with pain when the pinna is pulled and a swollen external ear canal. Diagnosis?', '["Acute otitis media", "Otitis externa", "Mastoiditis", "Foreign body"]', 1, 'Otitis externa (swimmer''s ear) involves the external canal. (Case Files)'),
    (v_topic_id, '56: What is the most common organism causing Otitis Externa?', '["Staphylococcus aureus", "Pseudomonas aeruginosa", "Streptococcus pneumoniae", "Aspergillus"]', 1, 'Pseudomonas is the most frequent pathogen in otitis externa. (Nelson)'),
    (v_topic_id, '57: A child presents with paroxysmal coughing followed by an inspiratory "whoop". What stage of Pertussis is this?', '["Catarrhal stage", "Paroxysmal stage", "Convalescent stage", "Incubation stage"]', 1, 'The paroxysmal stage is characterized by the classic cough. (Nelson)'),
    (v_topic_id, '58: A newborn has a "blueberry muffin" rash, cataracts, and a patent ductus arteriosus. What is the most likely congenital infection?', '["Cytomegalovirus", "Toxoplasmosis", "Rubella", "Syphilis"]', 2, 'Congenital rubella syndrome triad: PDA, cataracts, and sensorineural deafness. (Case Files)'),
    (v_topic_id, '59: Periventricular calcifications in a neonate with microcephaly are most suggestive of:', '["Congenital Toxoplasmosis", "Congenital CMV", "Congenital Rubella", "Congenital Herpes"]', 1, 'CMV calcifications are periventricular; Toxoplasmosis are diffuse. (Nelson)'),
    (v_topic_id, '60: Diffuse intracerebral calcifications and chorioretinitis in a neonate suggest:', '["Congenital CMV", "Congenital Toxoplasmosis", "Congenital Syphilis", "Congenital HIV"]', 1, 'Classic findings of congenital toxoplasmosis. (Harriet Lane)'),
    (v_topic_id, '61: A 1-year-old child presents with a fever of 104F and a generalized seizure lasting 2 minutes. The child is now back to baseline. Diagnosis?', '["Epilepsy", "Simple febrile seizure", "Complex febrile seizure", "Meningitis"]', 1, 'Simple febrile seizures are generalized, <15 mins, and occur once in 24 hours. (Nelson)'),
    (v_topic_id, '62: What is the management for a child with a first simple febrile seizure?', '["Start daily Phenobarbital", "Perform an urgent CT scan", "Reassurance and fever control", "Lumbar puncture for all"]', 2, 'Simple febrile seizures are benign and do not require long-term anticonvulsants. (AAP)'),
    (v_topic_id, '63: A child presents with fever, dysphagia, and a bulging of the posterior pharyngeal wall. Diagnosis?', '["Peritonsillar abscess", "Retropharyngeal abscess", "Epiglottitis", "Croup"]', 1, 'Retropharyngeal abscess is common in children <6 and presents with neck stiffness and posterior bulging. (Case Files)'),
    (v_topic_id, '64: A teenager presents with fever, severe sore throat, "hot potato" voice, and uvular deviation. Diagnosis?', '["Retropharyngeal abscess", "Peritonsillar abscess (Quinsy)", "Diphtheria", "Mononucleosis"]', 1, 'Peritonsillar abscess is more common in adolescents and deviates the uvula. (Nelson)'),
    (v_topic_id, '65: What is the classic presentation of Diphtheria?', '["Barking cough", "Gray pseudomembrane on the pharynx", "Slapped cheek rash", "Strawberry tongue"]', 1, 'The pseudomembrane can cause airway obstruction. (Nelson)'),
    (v_topic_id, '66: A child presents with sudden onset of high fever, chills, and muscle aches during winter. Diagnosis?', '["Common cold", "Influenza", "Bacterial pneumonia", "RSV"]', 1, 'Influenza presents more acutely with systemic symptoms. (Harriet Lane)'),
    (v_topic_id, '67: What is the most common complication of Influenza in children?', '["Myocarditis", "Acute Otitis Media", "Encephalitis", "Reye Syndrome"]', 1, 'AOM occurs in up to 25% of children with flu. (Nelson)'),
    (v_topic_id, '68: A child with a viral illness was given aspirin and now has vomiting and altered mental status. Diagnosis?', '["Encephalitis", "Reye Syndrome", "Salicylate poisoning", "Meningitis"]', 1, 'Reye syndrome involves acute encephalopathy and fatty liver. (Case Files)'),
    (v_topic_id, '69: A child presents with a high fever and a rash that looks like "dewdrops on a rose petal". Diagnosis?', '["Measles", "Varicella (Chickenpox)", "Smallpox", "Rubella"]', 1, 'The classic description of Varicella lesions. (Nelson)'),
    (v_topic_id, '70: A child presents with fever and painful swelling of the jaw. The physician notes the swelling obscures the angle of the mandible. Diagnosis?', '["Lymphadenitis", "Parotitis (Mumps)", "Dental abscess", "Cystic hygroma"]', 1, 'Parotid swelling is the hallmark of Mumps. (Nelson)'),
    (v_topic_id, '71: What is the most common cause of acute bronchiolitis in children?', '["Adenovirus", "Respiratory Syncytial Virus (RSV)", "Influenza virus", "Rhinovirus"]', 1, 'RSV is responsible for the majority of bronchiolitis cases. (Harriet Lane)'),
    (v_topic_id, '72: A child presents with a "whooping" cough. Which of the following is the most important preventive measure?', '["Handwashing", "Palivizumab", "Vaccination (DTaP/Tdap)", "Prophylactic antibiotics"]', 2, 'Vaccination is the most effective way to prevent pertussis. (CDC)'),
    (v_topic_id, '73: A child presents with fever, abdominal pain, and "currant jelly" stools. Diagnosis?', '["Gastroenteritis", "Intussusception", "Meckel Diverticulum", "Appendicitis"]', 1, 'Intussusception can be triggered by viral infections (adenovirus) causing Peyer''s patch hypertrophy. (Case Files)'),
    (v_topic_id, '74: A child presents with a foul-smelling discharge from the nose and persistent localized congestion. Diagnosis?', '["Allergic rhinitis", "Sinusitis", "Nasal foreign body", "Common cold"]', 2, 'Unilateral foul discharge is highly suspicious for a foreign body. (Nelson)'),
    (v_topic_id, '75: A child has fever and a stiff neck. Brudzinski''s sign is positive. This indicates:', '["Meningeal irritation", "Hip dysplasia", "Appendicitis", "Gallbladder inflammation"]', 0, 'Brudzinski and Kernig signs are physical exam findings in meningitis. (Nelson)'),
    (v_topic_id, '76: A 15-year-old with a sore throat is treated with amoxicillin and develops a diffuse maculopapular rash. What is the likely underlying infection?', '["Streptococcal pharyngitis", "Infectious mononucleosis", "Scarlet fever", "Measles"]', 1, 'Amoxicillin/Ampicillin causes a rash in up to 90% of patients with EBV. (Case Files)'),
    (v_topic_id, '77: What is the most common cause of neonatal conjunctivitis on day 2-5 of life?', '["Chemical irritation", "Neisseria gonorrhoeae", "Chlamydia trachomatis", "Herpes Simplex Virus"]', 1, 'Gonococcal conjunctivitis is early and severe. (Harriet Lane)'),
    (v_topic_id, '78: What is the most common cause of neonatal conjunctivitis on day 5-14 of life?', '["Neisseria gonorrhoeae", "Chlamydia trachomatis", "Chemical", "Staphylococcus aureus"]', 1, 'Chlamydial conjunctivitis presents slightly later than gonococcal. (Nelson)'),
    (v_topic_id, '79: A 4-year-old child presents with a high fever, refusal to move the neck, and a muffled voice. X-ray shows widened prevertebral space. Diagnosis?', '["Croup", "Retropharyngeal abscess", "Epiglottitis", "Peritonsillar abscess"]', 1, 'Widened prevertebral space is the key X-ray finding for retropharyngeal abscess. (Nelson)'),
    (v_topic_id, '80: A child presents with an intensely itchy rash in the finger webs and wrist creases, worse at night. Diagnosis?', '["Eczema", "Scabies", "Contact dermatitis", "Impetigo"]', 1, 'Scabies is caused by Sarcoptes scabiei mites and involves linear burrows. (Case Files)'),
    (v_topic_id, '81: What is the first-line treatment for Scabies in children?', '["Topical Permethrin 5%", "Topical Hydrocortisone", "Oral Amoxicillin", "Topical Clotrimazole"]', 0, 'Permethrin cream applied from the neck down and left on overnight is the standard treatment. (Nelson)'),
    (v_topic_id, '82: A child presents with multiple small, flesh-colored, umbilicated papules. Diagnosis?', '["Warts", "Molluscum contagiosum", "Varicella", "Acne"]', 1, 'Molluscum is caused by a poxvirus and is characterized by central umbilication. (Harriet Lane)'),
    (v_topic_id, '83: A 10-year-old child presents with sudden onset of high fever, headache, and severe muscle and joint pain ("breakbone fever"). Diagnosis?', '["Malaria", "Dengue Fever", "Typhoid", "Leptospirosis"]', 1, 'Dengue is transmitted by Aedes mosquitoes and causes intense pain. (Nelson)'),
    (v_topic_id, '84: What is the most common cause of acute viral myocarditis in children?', '["Coxsackie B Virus", "Adenovirus", "Parvovirus B19", "All of the above"]', 3, 'These three viruses are among the most common causes of viral myocarditis. (Nelson)'),
    (v_topic_id, '85: A child presents with fever, a new heart murmur, and splinter hemorrhages. What is the most likely diagnosis?', '["Rheumatic fever", "Infective endocarditis", "Kawasaki disease", "Pericarditis"]', 1, 'Endocarditis should be suspected in a child with fever and a heart murmur, especially if they have pre-existing heart disease. (Case Files)'),
    (v_topic_id, '86: A child presents with migratory polyarthritis and a recent history of a sore throat. What is the most likely diagnosis?', '["Juvenile Idiopathic Arthritis", "Acute Rheumatic Fever", "Septic arthritis", "Lyme disease"]', 1, 'Migratory arthritis is a major Jones criterion for Rheumatic Fever. (Nelson)'),
    (v_topic_id, '87: Erythema marginatum is a skin finding associated with:', '["Lyme disease", "Acute Rheumatic Fever", "Kawasaki disease", "Systemic Lupus Erythematosus"]', 1, 'Erythema marginatum is a major Jones criterion. (Nelson)'),
    (v_topic_id, '88: Sydenham chorea is a neurological manifestation of:', '["Meningitis", "Acute Rheumatic Fever", "Infectious mononucleosis", "Wilson disease"]', 1, 'Chorea consists of rapid, purposeless, involuntary movements. (Case Files)'),
    (v_topic_id, '89: A child presents with "strawberry tongue". This can be seen in which two conditions?', '["Measles and Rubella", "Scarlet Fever and Kawasaki Disease", "Mononucleosis and Croup", "Epiglottitis and Bronchiolitis"]', 1, 'Both conditions present with an erythematous, bumpy tongue. (Nelson)'),
    (v_topic_id, '90: What is the most common cause of bronchiolitis in infants?', '["Parainfluenza", "RSV", "Adenovirus", "Mycoplasma"]', 1, 'RSV is the leading cause. (Nelson)'),
    (v_topic_id, '91: A child presents with fever, stiff neck, and photophobia. Brudzinski sign is positive. Next best step?', '["Head CT", "Lumbar Puncture", "Start antibiotics", "Blood culture"]', 1, 'If no signs of increased intracranial pressure, LP is the definitive diagnostic step for meningitis. (Harriet Lane)'),
    (v_topic_id, '92: A neonate has jaundice, hepatosplenomegaly, and a "snuffles" (bloody nasal discharge). Diagnosis?', '["Congenital Rubella", "Congenital Syphilis", "Congenital Toxoplasmosis", "Congenital CMV"]', 1, 'Snuffles is pathognomonic for congenital syphilis. (Case Files)'),
    (v_topic_id, '93: Hutchinson teeth and mulberry molars are late signs of:', '["Congenital Rubella", "Congenital Syphilis", "Congenital CMV", "Congenital HIV"]', 1, 'Late manifestations of untreated congenital syphilis. (Nelson)'),
    (v_topic_id, '94: A child presents with a high fever and a "barking" cough that improves with cold air. Treatment for moderate cases?', '["Antibiotics", "Nebulized epinephrine and oral dexamethasone", "Albuterol", "Cough suppressants"]', 1, 'Steroids and racemic epinephrine are the mainstays of croup management. (Harriet Lane)'),
    (v_topic_id, '95: A child has fever and ear pain. Examination shows fluid behind the ear drum but NO signs of acute inflammation. This is:', '["Acute otitis media", "Otitis media with effusion (OME)", "Otitis externa", "Bullous myringitis"]', 1, 'OME is the presence of fluid without acute infection symptoms. (Nelson)'),
    (v_topic_id, '96: What is the treatment for most cases of Otitis Media with Effusion (OME)?', '["Amoxicillin", "Observation and follow-up", "Myringotomy", "Antihistamines"]', 1, 'OME usually resolves spontaneously and does not require antibiotics. (AAP)'),
    (v_topic_id, '97: A 6-year-old child presents with acute onset of high fever and severe ear pain. The TM is bulging and opaque. Diagnosis?', '["OME", "AOM", "Otitis externa", "Perforated TM"]', 1, 'Bulging TM is the most specific sign of AOM. (Case Files)'),
    (v_topic_id, '98: A child presents with a red, painful eye with "stuck-shut" eyelids in the morning. Diagnosis?', '["Viral conjunctivitis", "Bacterial conjunctivitis", "Allergic conjunctivitis", "Blepharitis"]', 1, 'Purulent discharge and matting of the eyelids are typical for bacterial conjunctivitis. (Nelson)'),
    (v_topic_id, '99: A child presents with watery eye discharge, preauricular lymphadenopathy, and a recent cold. Diagnosis?', '["Bacterial conjunctivitis", "Viral conjunctivitis", "Allergic conjunctivitis", "Dacryocystitis"]', 1, 'Adenoviral infection is the most common cause of viral conjunctivitis. (Harriet Lane)'),
    (v_topic_id, '100: A child presents with intense eye itching and a "cobblestone" appearance of the palpebral conjunctiva. Diagnosis?', '["Viral conjunctivitis", "Allergic conjunctivitis", "Bacterial conjunctivitis", "Trachoma"]', 1, 'Cobblestoning is a hallmark of allergic conjunctivitis. (Nelson)'),
    (v_topic_id, '101: A 1-month-old infant presents with a paroxysmal cough and post-tussive emesis. The infant is not immunized. What is the most likely diagnosis?', '["Bronchiolitis", "Pertussis", "Chlamydia pneumonia", "Cystic fibrosis"]', 1, 'Pertussis should be suspected in any infant with paroxysmal coughing. (Case Files)'),
    (v_topic_id, '102: What is the treatment for Chlamydia trachomatis conjunctivitis in a neonate?', '["Topical erythromycin", "Oral erythromycin", "Topical gentamicin", "No treatment needed"]', 1, 'Systemic treatment is required to prevent subsequent chlamydial pneumonia. (Nelson)'),
    (v_topic_id, '103: A child presents with a "honey-colored" crusty lesion on the corner of the mouth. What is the most likely organism?', '["Streptococcus pyogenes", "Staphylococcus aureus", "Both A and B", "Herpes simplex"]', 2, 'Impetigo is primarily caused by S. aureus or S. pyogenes. (Nelson)'),
    (v_topic_id, '104: A child presents with a large, painful, red, fluctuant mass on the thigh. Diagnosis?', '["Cellulitis", "Abscess", "Furuncle", "Erysipelas"]', 1, 'An abscess is a localized collection of pus. (Harriet Lane)'),
    (v_topic_id, '105: What is the most important step in managing a cutaneous abscess?', '["Systemic antibiotics", "Incision and Drainage (I&D)", "Warm compresses", "Topical antibiotics"]', 1, 'I&D is the definitive treatment for abscesses. (Case Files)'),
    (v_topic_id, '106: A child presents with a red, hot, tender, poorly demarcated area of skin on the leg. Diagnosis?', '["Cellulitis", "Erysipelas", "Abscess", "Necrotizing fasciitis"]', 0, 'Cellulitis is an infection of the deeper dermis and subcutaneous tissues. (Nelson)'),
    (v_topic_id, '107: A child presents with a sharply demarcated, bright red, raised area of skin on the face. Diagnosis?', '["Cellulitis", "Erysipelas", "Impetigo", "Scarlet fever"]', 1, 'Erysipelas is a more superficial form of cellulitis, often caused by Group A Strep. (Nelson)'),
    (v_topic_id, '108: A child presents with rapid onset of severe pain out of proportion to exam findings, fever, and skin that looks "dusky" or "purple". Diagnosis?', '["Cellulitis", "Necrotizing fasciitis", "Erysipelas", "Toxic Shock Syndrome"]', 1, 'Necrotizing fasciitis is a surgical emergency. (Harriet Lane)'),
    (v_topic_id, '109: What is the most common cause of cellulitis in children?', '["Group A Streptococcus and S. aureus", "Pseudomonas", "E. coli", "Haemophilus influenzae"]', 0, 'Gram-positive cocci are the most frequent causes. (Case Files)'),
    (v_topic_id, '110: A child presents with fever and back pain. Physical exam shows tenderness over a vertebral body. Diagnosis?', '["Meningitis", "Vertebral osteomyelitis", "Discitis", "Spinal epidural abscess"]', 2, 'Discitis is an infection/inflammation of the intervertebral disc space, common in young children. (Nelson)'),
    (v_topic_id, '111: A child presents with a painful, swollen joint. Synovial fluid shows 100,000 WBCs. What is the most likely organism?', '["Kingella kingae", "Staphylococcus aureus", "Borrelia burgdorferi", "Streptococcus pneumoniae"]', 1, 'S. aureus is the most common cause of septic arthritis. (Harriet Lane)'),
    (v_topic_id, '112: A child presents with "walking pneumonia" (low fever, dry cough, interstitial pattern). Cold agglutinin titer is elevated. Diagnosis?', '["Mycoplasma pneumoniae", "RSV", "Streptococcus pneumoniae", "Legionella"]', 0, 'Cold agglutinins are often positive in Mycoplasma infections. (Case Files)'),
    (v_topic_id, '113: What is the treatment for Mycoplasma pneumonia in an 11-year-old?', '["Amoxicillin", "Azithromycin", "Ceftriaxone", "Vancomycin"]', 1, 'Macrolides are the drug of choice for atypical pneumonia. (Nelson)'),
    (v_topic_id, '114: A neonate has a high fever and is lethargic. You suspect sepsis. What are the three most common organisms?', '["GBS, E. coli, Listeria", "S. aureus, H. influenzae, S. pneumoniae", "Klebsiella, Pseudomonas, Serratia", "GBS, S. aureus, Enterococcus"]', 0, 'The "classic" trio of neonatal pathogens. (Harriet Lane)'),
    (v_topic_id, '115: Empiric treatment for neonatal sepsis should include:', '["Vancomycin and Cefepime", "Ampicillin and Gentamicin (or Cefotaxime)", "Ceftriaxone and Vancomycin", "Penicillin and Tobramycin"]', 1, 'Ampicillin covers GBS and Listeria; Gentamicin covers E. coli. (Nelson)'),
    (v_topic_id, '116: Why is Ceftriaxone generally avoided in neonates <28 days old?', '["Risk of ototoxicity", "Risk of kernicterus (displaces bilirubin from albumin)", "Risk of renal failure", "Ineffective against neonatal pathogens"]', 1, 'Ceftriaxone can cause biliary sludging and displace bilirubin. (Case Files)'),
    (v_topic_id, '117: A child presents with high fever, neck stiffness, and a petechial rash. CSF shows G- diplococci. Diagnosis?', '["S. pneumoniae meningitis", "Meningococcal meningitis (Neisseria)", "H. influenzae meningitis", "Viral meningitis"]', 1, 'Neisseria meningitidis is a gram-negative diplococcus. (Nelson)'),
    (v_topic_id, '118: What is the most common cause of bacterial meningitis in infants 1-23 months old?', '["GBS", "S. pneumoniae", "N. meningitidis", "Listeria"]', 1, 'S. pneumoniae has become the leading cause after the Hib vaccine. (Harriet Lane)'),
    (v_topic_id, '119: Prophylaxis for close contacts of a patient with Meningococcal meningitis is:', '["Rifampin", "Amoxicillin", "Acyclovir", "No prophylaxis needed"]', 0, 'Rifampin, Ciprofloxacin (adults), or Ceftriaxone can be used. (Case Files)'),
    (v_topic_id, '120: A child presents with high fever, headache, and confusion. CSF is normal except for elevated RBCs and temporal lobe changes on MRI. Diagnosis?', '["Bacterial meningitis", "Herpes Simplex Virus (HSV) encephalitis", "Enteroviral meningitis", "Rabies"]', 1, 'HSV has a predilection for the temporal lobes. (Nelson)'),
    (v_topic_id, '121: What is the treatment for HSV encephalitis?', '["Vancomycin", "Acyclovir", "Ceftriaxone", "Ganciclovir"]', 1, 'Acyclovir should be started promptly if HSV is suspected. (Harriet Lane)'),
    (v_topic_id, '122: A child presents with "Hand-Foot-and-Mouth Disease". What is the most likely virus?', '["Coxsackievirus A16", "Herpes Simplex Virus 1", "Parvovirus B19", "Varicella Zoster Virus"]', 0, 'Coxsackie A16 is the classic cause. (Nelson)'),
    (v_topic_id, '123: A child presents with fever and a "strawberry tongue" followed by desquamation of the skin on the fingertips. Diagnosis?', '["Scarlet fever", "Kawasaki disease", "Toxic Shock Syndrome", "Staphylococcal Scalded Skin Syndrome"]', 1, 'Periungual desquamation is a characteristic feature of the subacute phase of Kawasaki. (Case Files)'),
    (v_topic_id, '124: What is the most common cause of viral pharyngitis in children?', '["Adenovirus", "Epstein-Barr Virus", "Group A Streptococcus", "Rhinovirus"]', 3, 'Rhinoviruses and other "cold" viruses are the most frequent causes. (Nelson)'),
    (v_topic_id, '125: A child presents with fever, pharyngitis, and conjunctivitis. This triad is classic for:', '["Infectious mononucleosis", "Adenoviral infection (Pharyngoconjunctival fever)", "Measles", "Kawasaki disease"]', 1, 'Adenovirus often causes this specific cluster of symptoms. (Case Files)'),
    (v_topic_id, '126: A child presents with sore throat and a "gray-white" membrane on the tonsils. When the membrane is scraped, it bleeds. Diagnosis?', '["Streptococcal pharyngitis", "Diphtheria", "Mononucleosis", "Candidiasis"]', 1, 'Corynebacterium diphtheriae produces a characteristic adherent pseudomembrane. (Nelson)'),
    (v_topic_id, '127: A child presents with generalized lymphadenopathy and a positive heterophile antibody test. Diagnosis?', '["Cat scratch disease", "Infectious mononucleosis", "HIV", "Tuberculosis"]', 1, 'The heterophile antibody (Monospot) test is used to diagnose EBV. (Harriet Lane)'),
    (v_topic_id, '128: A child with a cat scratch develops a tender lymph node in the axilla. What is the treatment?', '["Azithromycin", "Amoxicillin", "Ceftriaxone", "None needed (usually self-limiting)"]', 3, 'Most cases of Cat Scratch Disease are self-limiting; Azithromycin can be used in severe cases. (Case Files)'),
    (v_topic_id, '129: What is the most common cause of fungal skin infections in children?', '["Candida albicans", "Trichophyton tonsurans", "Malassezia furfur", "Sporothrix schenckii"]', 1, 'Trichophyton is a common cause of tinea capitis and corporis. (Nelson)'),
    (v_topic_id, '130: A child has an itchy, red rash in the groin area that SPARES the scrotum. Diagnosis?', '["Candidiasis", "Tinea cruris (Jock itch)", "Intertrigo", "Contact dermatitis"]', 1, 'Tinea cruris typically spares the scrotum; candidiasis often involves it. (Nelson)'),
    (v_topic_id, '131: A child presents with "diaper rash" that is bright red and has "satellite lesions". Diagnosis?', '["Irritant dermatitis", "Candidiasis", "Sebehorreic dermatitis", "Scabies"]', 1, 'Satellite lesions are classic for Candida diaper dermatitis. (Harriet Lane)'),
    (v_topic_id, '132: What is the treatment for Candidal diaper rash?', '["Zinc oxide", "Topical Nystatin or Clotrimazole", "Topical Hydrocortisone", "Topical Mupirocin"]', 1, 'Antifungal creams are necessary. (Nelson)'),
    (v_topic_id, '133: A child presents with a scaly, hypopigmented rash on the chest and back that becomes more noticeable after sun exposure. Diagnosis?', '["Vitiligo", "Pityriasis versicolor (Tinea versicolor)", "Pityriasis alba", "Tinea corporis"]', 1, 'Caused by Malassezia species; "spaghetti and meatballs" appearance on KOH. (Case Files)'),
    (v_topic_id, '134: A child presents with a "herald patch" followed by a "Christmas tree" distribution of smaller lesions on the back. Diagnosis?', '["Pityriasis rosea", "Secondary syphilis", "Guttate psoriasis", "Tinea corporis"]', 0, 'Pityriasis rosea is a benign, self-limiting condition. (Nelson)'),
    (v_topic_id, '135: A child has warts on the fingers. What is the causative agent?', '["Herpes Simplex Virus", "Human Papillomavirus (HPV)", "Poxvirus", "Varicella Zoster Virus"]', 1, 'Verruca vulgaris is caused by various HPV types. (Harriet Lane)'),
    (v_topic_id, '136: A child presents with multiple small, grouped vesicles on an erythematous base near the lip. Diagnosis?', '["Impetigo", "Herpes Labialis (Cold sore)", "Aphthous ulcer", "Syphilis chancre"]', 1, 'Recurrent HSV-1 infection. (Case Files)'),
    (v_topic_id, '137: A child presents with high fever, toxic appearance, and a "sunburn-like" rash that later desquamates. He has hypotension and multi-organ failure. Diagnosis?', '["Kawasaki disease", "Toxic Shock Syndrome (TSS)", "Scarlet fever", "Meningococcemia"]', 1, 'TSS is usually caused by S. aureus or S. pyogenes exotoxins. (Nelson)'),
    (v_topic_id, '138: What is the most common cause of bronchiolitis?', '["RSV", "Rhinovirus", "Influenza", "Adenovirus"]', 0, 'RSV is the leading cause. (Nelson)'),
    (v_topic_id, '139: A child presents with sudden onset of fever, cough, and subglottic narrowing on X-ray ("steeple sign"). Diagnosis?', '["Epiglottitis", "Croup", "Bacterial tracheitis", "Foreign body"]', 1, 'The steeple sign is characteristic of croup. (Harriet Lane)'),
    (v_topic_id, '140: A child with croup fails to improve with epinephrine and looks increasingly toxic. You should suspect:', '["Severe croup", "Bacterial tracheitis", "Epiglottitis", "Pneumonia"]', 1, 'Bacterial tracheitis is often a secondary bacterial infection of the subglottic area. (Case Files)'),
    (v_topic_id, '141: What is the most common organism causing Bacterial Tracheitis?', '["S. pneumoniae", "S. aureus", "H. influenzae", "Moraxella catarrhalis"]', 1, 'S. aureus is the most frequent pathogen. (Nelson)'),
    (v_topic_id, '142: A child presents with fever and localized facial swelling near the jaw. A dental abscess is suspected. What is the best initial management?', '["Antibiotics", "Antibiotics and referral to a dentist for drainage/extraction", "Incision and drainage in the ER", "Warm compresses only"]', 1, 'Definitive dental care is needed along with antibiotics. (Harriet Lane)'),
    (v_topic_id, '143: A child presents with a "swollen eye". He has proptosis and pain with extraocular movements. Next step?', '["Oral antibiotics", "CT scan of the orbits and sinuses", "Topical antibiotics", "Wait and watch"]', 1, 'CT is needed to evaluate for orbital cellulitis and abscess. (Case Files)'),
    (v_topic_id, '144: A child with a runny nose and cough develops facial pain and pressure. Diagnosis?', '["Common cold", "Acute Sinusitis", "Allergic rhinitis", "Nasal polyps"]', 1, 'Sinusitis is often a complication of a viral URI. (Nelson)'),
    (v_topic_id, '145: What is the most common cause of acute bacterial sinusitis in children?', '["S. pneumoniae, H. influenzae, M. catarrhalis", "S. aureus", "Pseudomonas", "Anaerobes"]', 0, 'The same "standard" respiratory pathogens that cause AOM. (Harriet Lane)'),
    (v_topic_id, '146: A 2-year-old child has a fever and is pulling at his ear. The TM is retracted and has a yellowish color. Diagnosis?', '["Acute otitis media", "Otitis media with effusion", "Cholesteatoma", "Eustachian tube dysfunction"]', 1, 'Yellowish color and retraction suggest fluid without acute infection. (Nelson)'),
    (v_topic_id, '147: A child presents with sudden onset of fever and a "hot potato" voice. On exam, one tonsil is displaced medially and the uvula is deviated. Diagnosis?', '["Retropharyngeal abscess", "Peritonsillar abscess", "Diphtheria", "Epiglottitis"]', 1, 'Peritonsillar abscess (Quinsy) is more common in older children/teens. (Case Files)'),
    (v_topic_id, '148: A child presents with high fever and a "gray" pseudomembrane on the pharynx. He has "bull neck" lymphadenopathy. Diagnosis?', '["Mononucleosis", "Diphtheria", "Scarlet fever", "Vincent''s angina"]', 1, 'Classic presentation of Corynebacterium diphtheriae. (Nelson)'),
    (v_topic_id, '149: What is the most common cause of traveler''s diarrhea in children?', '["Giardia lamblia", "Enterotoxigenic E. coli (ETEC)", "Shigella", "Salmonella"]', 1, 'ETEC is the leading cause of traveler''s diarrhea worldwide. (Harriet Lane)'),
    (v_topic_id, '150: A child presents with greasy, foul-smelling diarrhea after drinking stream water. Diagnosis?', '["Giardiasis", "Cryptosporidiosis", "Amebiasis", "Rotavirus"]', 0, 'Giardia is a common waterborne parasite. (Case Files)'),
    (v_topic_id, '151: What is the treatment for Giardiasis?', '["Amoxicillin", "Metronidazole or Tinidazole", "Azithromycin", "Ciprofloxacin"]', 1, 'Anti-protozoal medications are effective. (Nelson)'),
    (v_topic_id, '152: A child presents with high fever, bloody diarrhea, and a seizure. Diagnosis?', '["Salmonella", "Shigella", "Campylobacter", "E. coli O157:H7"]', 1, 'Shigella can produce neurotoxins leading to seizures. (Nelson)'),
    (v_topic_id, '153: What is the most common cause of bacterial gastroenteritis in the US?', '["Salmonella", "Campylobacter", "Shigella", "Yersinia"]', 1, 'Campylobacter jejuni is a very frequent cause of diarrhea. (Harriet Lane)'),
    (v_topic_id, '154: A child presents with diarrhea and abdominal pain that mimics appendicitis. Which organism is known for this?', '["Yersinia enterocolitica", "Salmonella", "Rotavirus", "Giardia"]', 0, 'Yersinia can cause mesenteric adenitis, mimicking appendicitis. (Case Files)'),
    (v_topic_id, '155: A child has watery diarrhea and vomiting. He has been around a pet turtle. Organism?', '["Salmonella", "Shigella", "E. coli", "Campylobacter"]', 0, 'Reptiles are frequent carriers of non-typhoidal Salmonella. (Nelson)'),
    (v_topic_id, '156: A 2-year-old child presents with sudden onset of a generalized, tonic-clonic seizure during a fever. It lasts 5 minutes. Diagnosis?', '["Simple febrile seizure", "Complex febrile seizure", "Status epilepticus", "Absence seizure"]', 0, 'Fits the criteria for a simple febrile seizure. (Harriet Lane)'),
    (v_topic_id, '157: A child presents with a "honey-colored" crust on the chin. This is most likely:', '["Impetigo", "Herpes", "Eczema", "Psoriasis"]', 0, 'Impetigo is classic for honey-colored crusts. (Nelson)'),
    (v_topic_id, '158: What is the treatment for extensive or bullous impetigo?', '["Topical mupirocin", "Oral Cephalexin or Dicloxacillin", "IV Penicillin", "Oral Amoxicillin"]', 1, 'Systemic antibiotics are used for widespread or bullous lesions. (Case Files)'),
    (v_topic_id, '159: A child presents with a painful, red, swollen joint. Fever is present. Joint fluid has 120,000 WBCs. Next step?', '["Oral antibiotics", "Surgical drainage and IV antibiotics", "NSAIDs", "Wait for cultures"]', 1, 'Septic arthritis is a surgical emergency to prevent joint destruction. (Harriet Lane)'),
    (v_topic_id, '160: What is the most common cause of bacterial pneumonia in neonates?', '["GBS and E. coli", "S. pneumoniae", "S. aureus", "H. influenzae"]', 0, 'The same pathogens that cause neonatal sepsis. (Nelson)'),
    (v_topic_id, '161: What is the most common cause of pneumonia in infants 1-3 months old?', '["S. pneumoniae", "Chlamydia trachomatis", "RSV", "All of the above"]', 3, 'Viral (RSV) and atypical (Chlamydia) are common, but S. pneumoniae is also prevalent. (Nelson)'),
    (v_topic_id, '162: A child presents with a "staccato" cough and peripheral eosinophilia. No fever is present. Diagnosis?', '["RSV bronchiolitis", "Chlamydia trachomatis pneumonia", "Pertussis", "Asthma"]', 1, 'Afebrile, staccato cough, and eosinophilia are classic for Chlamydia in early infancy. (Case Files)'),
    (v_topic_id, '163: A 4-year-old child presents with a rapid onset of high fever and a muffled "hot potato" voice. He is sitting forward and drooling. Diagnosis?', '["Croup", "Epiglottitis", "Retropharyngeal abscess", "Foreign body"]', 1, 'The "tripod" position and drooling are hallmarks of epiglottitis. (Nelson)'),
    (v_topic_id, '164: What is the most common organism causing Epiglottitis in unimmunized children?', '["S. pneumoniae", "H. influenzae type b (Hib)", "S. aureus", "Group A Strep"]', 1, 'Hib was the primary cause before widespread vaccination. (Harriet Lane)'),
    (v_topic_id, '165: A child presents with fever and a bulging, posterior pharyngeal wall. Neck extension is painful. Diagnosis?', '["Epiglottitis", "Retropharyngeal abscess", "Peritonsillar abscess", "Croup"]', 1, 'Retropharyngeal abscesses often cause neck stiffness and limited extension. (Case Files)'),
    (v_topic_id, '166: A teenager presents with severe throat pain, difficulty opening the mouth (trismus), and deviation of the uvula. Diagnosis?', '["Mononucleosis", "Peritonsillar abscess", "Retropharyngeal abscess", "Diphtheria"]', 1, 'Trismus and uvular deviation are key signs of a peritonsillar abscess. (Nelson)'),
    (v_topic_id, '167: What is the most common cause of acute pharyngitis in children overall?', '["Group A Streptococcus", "Viral infections", "Mycoplasma", "Corynebacterium"]', 1, 'Viruses are the most frequent cause of sore throats in children. (Harriet Lane)'),
    (v_topic_id, '168: A child presents with fever, sore throat, and small vesicles on the posterior oropharynx (soft palate). Diagnosis?', '["Herpetic gingivostomatitis", "Herpangina", "Hand-foot-mouth disease", "Aphthous ulcers"]', 1, 'Herpangina is caused by Coxsackie A and involves the posterior mouth. (Case Files)'),
    (v_topic_id, '169: A 2-year-old presents with high fever and multiple painful ulcers on the anterior tongue, gums, and lips. Diagnosis?', '["Herpangina", "Herpetic gingivostomatitis", "Hand-foot-mouth disease", "Vincent''s angina"]', 1, 'HSV-1 infection in children often involves the anterior oral structures. (Nelson)'),
    (v_topic_id, '170: What is the most common complication of varicella in healthy children?', '["Encephalitis", "Secondary bacterial skin infection", "Pneumonia", "Cerebellar ataxia"]', 1, 'S. aureus or S. pyogenes infections are common due to scratching. (Harriet Lane)'),
    (v_topic_id, '171: A child with varicella develops a sudden onset of unsteady gait and tremors about a week after the rash starts. Diagnosis?', '["Acute cerebellar ataxia", "Encephalitis", "Reye syndrome", "Meningitis"]', 0, 'Post-varicella cerebellar ataxia is usually a benign, self-limiting condition. (Nelson)'),
    (v_topic_id, '172: A child presents with fever and "slapped cheek" rash. A week later, he develops a lacy rash on his trunk. He is now feeling fine. Can he return to school?', '["No, he is still contagious", "Yes, he is no longer contagious once the rash appears", "No, wait for 5 more days", "Yes, if he has no fever"]', 1, 'The rash in Fifth Disease is an immune-mediated phenomenon; the child is not contagious at this stage. (Case Files)'),
    (v_topic_id, '173: A child with high fever for 3 days suddenly feels better, but then develops a pink maculopapular rash on the trunk. Diagnosis?', '["Measles", "Roseola", "Rubella", "Scarlet fever"]', 1, 'Classic description of Roseola (Exanthema Subitum). (Nelson)'),
    (v_topic_id, '174: What is the major concern with Roseola Infantum?', '["Pneumonia", "Febrile seizures", "Encephalitis", "Myocarditis"]', 1, 'Roseola is a common cause of febrile seizures due to the rapid rise in temperature. (Harriet Lane)'),
    (v_topic_id, '175: A child has a fever and a cough. Today a rash started on his face and is moving down his body. You see small white spots on his buccal mucosa. Diagnosis?', '["Rubella", "Measles (Rubeola)", "Scarlet fever", "Roseola"]', 1, 'Koplik spots are pathognomonic for Measles. (Nelson)'),
    (v_topic_id, '176: A child presents with fever, posterior auricular lymphadenopathy, and a cephalocaudal rash. Diagnosis?', '["Measles", "Rubella (German Measles)", "Roseola", "Fifth disease"]', 1, 'Rubella is often milder than Measles and features characteristic lymphadenopathy. (Case Files)'),
    (v_topic_id, '177: What is the most common cause of "swimmer''s ear" (Otitis Externa)?', '["Staphylococcus aureus", "Pseudomonas aeruginosa", "Candida", "Aspergillus"]', 1, 'Pseudomonas thrives in moist environments. (Nelson)'),
    (v_topic_id, '178: A child presents with pain on movement of the tragus and a narrow, swollen ear canal. Treatment?', '["Oral amoxicillin", "Topical antibiotic drops (e.g., Ciprofloxacin/Dexamethasone)", "Myringotomy", "Systemic steroids"]', 1, 'Topical therapy is the mainstay for uncomplicated otitis externa. (Harriet Lane)'),
    (v_topic_id, '179: A child with acute otitis media has been on amoxicillin for 48 hours but still has high fever and ear pain. Next step?', '["Switch to Amoxicillin-Clavulanate (Augmentin)", "Continue amoxicillin for 10 days", "Perform a lumbar puncture", "Give IV ceftriaxone"]', 0, 'Failure to respond to amoxicillin suggests resistant S. pneumoniae or H. influenzae. (AAP)'),
    (v_topic_id, '180: What is the most common organism causing Urinary Tract Infection (UTI) in children?', '["Proteus", "Klebsiella", "E. coli", "Staph saprophyticus"]', 2, 'E. coli is the cause in >80% of cases. (Nelson)'),
    (v_topic_id, '181: A 10-month-old male with his first UTI should undergo which imaging study after the infection resolves?', '["Renal Ultrasound", "Voiding Cystourethrogram (VCUG)", "CT scan", "DMSA scan"]', 0, 'Renal ultrasound is recommended for all children <2 years with their first febrile UTI. (AAP)'),
    (v_topic_id, '182: A 2-year-old female has her second febrile UTI. What imaging study is now indicated to look for vesicoureteral reflux (VUR)?', '["Renal Ultrasound", "VCUG", "IVP", "MRI"]', 1, 'VCUG is recommended after a second febrile UTI or if the ultrasound is abnormal. (AAP)'),
    (v_topic_id, '183: A child presents with "currant jelly" stools and intermittent abdominal pain. What is the most likely lead point or trigger?', '["Meckel Diverticulum", "Peyer''s patch hypertrophy (viral)", "Polyp", "Intestinal malrotation"]', 1, 'Viral infections often cause lymphoid hyperplasia (Peyer''s patches), which can trigger intussusception. (Case Files)'),
    (v_topic_id, '184: What is the most common cause of bloody diarrhea with a low-grade fever in children?', '["Rotavirus", "Campylobacter", "Salmonella", "Shigella"]', 1, 'Campylobacter jejuni is a very common cause of bacterial enteritis. (Nelson)'),
    (v_topic_id, '185: A child presents with bloody diarrhea and abdominal pain. He recently played with a puppy that had diarrhea. Organism?', '["Salmonella", "Campylobacter", "Yersinia", "E. coli"]', 1, 'Campylobacter is often zoonotic (puppies, poultry). (Nelson)'),
    (v_topic_id, '186: A 2-year-old child presents with bloody diarrhea and a seizure. Organism?', '["Salmonella", "Shigella", "Giardia", "Norovirus"]', 1, 'Shigella sonnei or flexneri can cause seizures in young children. (Harriet Lane)'),
    (v_topic_id, '187: A child presents with diarrhea, microangiopathic hemolytic anemia, and renal failure. What is the most likely pathogen?', '["E. coli O157:H7", "Shigella dysenteriae", "Both A and B", "Salmonella typhi"]', 2, 'Both can produce Shiga toxin, leading to HUS. (Case Files)'),
    (v_topic_id, '188: What is the most important treatment for a child with suspected Hemolytic Uremic Syndrome (HUS)?', '["Antibiotics", "Supportive care (fluids, dialysis if needed)", "Anti-motility agents", "Steroids"]', 1, 'Antibiotics may worsen HUS; treatment is primarily supportive. (Nelson)'),
    (v_topic_id, '189: A child presents with greasy, floating, foul-smelling diarrhea after a camping trip. Diagnosis?', '["Giardiasis", "Cryptosporidiosis", "Amebiasis", "Celiac disease"]', 0, 'Giardia lamblia is a common parasitic cause of malabsorptive diarrhea. (Harriet Lane)'),
    (v_topic_id, '190: A child presents with fever and a "strawberry tongue" and a sandpaper-like rash. This is most likely:', '["Kawasaki disease", "Scarlet fever", "Measles", "Toxic Shock Syndrome"]', 1, 'Scarlet fever (Group A Strep) is characterized by this specific rash. (Case Files)'),
    (v_topic_id, '191: A child presents with multiple honey-colored crusted lesions on the face. Diagnosis?', '["Impetigo", "Erysipelas", "Cellulitis", "Eczema herpeticum"]', 0, 'Impetigo is classic for "honey-colored" crusts. (Nelson)'),
    (v_topic_id, '192: A 4-year-old child presents with fever and refusal to use his right leg. The hip is held in external rotation and flexion. Joint aspirate has 80,000 WBCs. Diagnosis?', '["Transient synovitis", "Septic arthritis", "Osteomyelitis", "Legg-Calve-Perthes disease"]', 1, 'High WBC in joint fluid is diagnostic for septic arthritis. (Harriet Lane)'),
    (v_topic_id, '193: What is the most common cause of septic arthritis in a neonate?', '["Staphylococcus aureus", "Group B Streptococcus", "E. coli", "All of the above"]', 3, 'Neonatal septic arthritis can be caused by any of the standard neonatal pathogens. (Nelson)'),
    (v_topic_id, '194: What is the most common cause of osteomyelitis in children?', '["S. aureus", "Group A Strep", "Pseudomonas", "Salmonella"]', 0, 'S. aureus is the leading cause in all age groups except those with specific risks. (Case Files)'),
    (v_topic_id, '195: A child with a puncture wound through a sneaker develops osteomyelitis of the foot. What organism should you be especially concerned about?', '["Staphylococcus aureus", "Pseudomonas aeruginosa", "Salmonella", "E. coli"]', 1, 'Pseudomonas is associated with puncture wounds through shoes. (Nelson)'),
    (v_topic_id, '196: A child presents with fever, headache, and a petechial rash. Diagnosis?', '["Meningococcemia", "RMSF", "Either A or B", "Measles"]', 2, 'Both can present with fever and a petechial/purpuric rash. (Harriet Lane)'),
    (v_topic_id, '197: A child presents with a high fever and a rash that started on his wrists and ankles and moved to his trunk. Treatment?', '["Amoxicillin", "Doxycycline", "Azithromycin", "Vancomycin"]', 1, 'Doxycycline is first-line for RMSF in all ages. (CDC)'),
    (v_topic_id, '198: A child presents with a circular red rash with central clearing on his leg. He was recently in a wooded area. Diagnosis?', '["Tinea corporis", "Lyme Disease (Erythema Migrans)", "Granuloma annulare", "Nummular eczema"]', 1, 'Erythema migrans is the pathognomonic early sign of Lyme disease. (Case Files)'),
    (v_topic_id, '199: A child presents with a "slapped cheek" appearance. This is characteristic of:', '["Fifth Disease (Erythema Infectiosum)", "Roseola", "Rubella", "Scarlet fever"]', 0, 'Parvovirus B19 causes the "slapped cheek" look. (Nelson)'),
    (v_topic_id, '200: A child with a history of atopic dermatitis presents with a sudden eruption of painful, punched-out vesicles and fever. Diagnosis?', '["Impetigo", "Eczema herpeticum", "Hand-foot-mouth disease", "Varicella"]', 1, 'Eczema herpeticum is a disseminated HSV infection in patients with broken skin barriers. (Harriet Lane)'),
    (v_topic_id, '201: What is the most common cause of acute orbital cellulitis?', '["Bacterial sinusitis", "Direct inoculation from trauma", "Dental infection", "Hematogenous spread"]', 0, 'Spread from the ethmoid sinuses is the most common source. (Nelson)'),
    (v_topic_id, '202: Which of the following is a sign of orbital cellulitis but NOT preseptal cellulitis?', '["Eyelid edema", "Eyelid erythema", "Ophthalmoplegia (limited eye movement)", "Fever"]', 2, 'Orbital cellulitis affects the structures within the orbit, restricting eye movement. (Case Files)'),
    (v_topic_id, '203: A child presents with multiple small, flesh-colored papules with central umbilication. What is the treatment?', '["Antibiotics", "Watchful waiting (usually self-resolving)", "Topical steroids", "Surgical excision"]', 1, 'Molluscum contagiosum is a self-limiting viral infection. (Nelson)'),
    (v_topic_id, '204: A child presents with a red, itchy scalp and nits attached to the hair. Treatment?', '["Topical Permethrin", "Topical Ketoconazole", "Oral Griseofulvin", "Topical Hydrocortisone"]', 0, 'Permethrin is first-line for head lice. (Harriet Lane)'),
    (v_topic_id, '205: A child has a bald, scaly patch on the scalp with "black dots" and cervical lymphadenopathy. Diagnosis?', '["Alopecia areata", "Tinea capitis", "Trichotillomania", "Seborrheic dermatitis"]', 1, 'Tinea capitis is a fungal infection of the scalp. (Case Files)'),
    (v_topic_id, '206: What is the treatment for Tinea capitis?', '["Topical miconazole", "Oral Griseofulvin or Terbinafine", "Topical hydrocortisone", "Oral amoxicillin"]', 1, 'Scalp fungal infections require systemic treatment. (Nelson)'),
    (v_topic_id, '207: A child presents with a painful swelling in front of the ear that obscures the angle of the mandible. Diagnosis?', '["Lymphadenitis", "Mumps (Parotitis)", "Parotid stone", "Dental abscess"]', 1, 'Parotitis is the classic presentation of Mumps. (Nelson)'),
    (v_topic_id, '208: A child presents with high fever, barking cough, and stridor. He looks toxic and is not responding to racemic epinephrine. Diagnosis?', '["Severe Croup", "Bacterial tracheitis", "Epiglottitis", "Retropharyngeal abscess"]', 1, 'Bacterial tracheitis is a toxic-appearing child with symptoms of croup. (Harriet Lane)'),
    (v_topic_id, '209: What is the most common organism found in Bacterial Tracheitis?', '["S. pneumoniae", "Staph aureus", "H. influenzae", "Group A Strep"]', 1, 'S. aureus is the most frequent pathogen isolated. (Nelson)'),
    (v_topic_id, '210: A neonate presents with purulent eye discharge on day 3 of life. Gram stain shows G- diplococci. Treatment?', '["Topical erythromycin", "IV/IM Ceftriaxone", "Oral erythromycin", "No treatment needed"]', 1, 'Gonococcal conjunctivitis requires systemic antibiotics. (Case Files)'),
    (v_topic_id, '211: A neonate presents with conjunctivitis on day 10 of life. The discharge is watery/mucoid. Diagnosis?', '["Gonococcal conjunctivitis", "Chlamydial conjunctivitis", "Chemical conjunctivitis", "HSV conjunctivitis"]', 1, 'Chlamydia typically presents between 5-14 days of life. (Nelson)'),
    (v_topic_id, '212: A neonate has a high fever and a bulging fontanelle. CSF shows a high WBC count and G+ cocci in pairs. Organism?', '["GBS", "S. pneumoniae", "E. coli", "Listeria"]', 1, 'S. pneumoniae are gram-positive cocci in pairs. (Harriet Lane)'),
    (v_topic_id, '213: A child presents with fever and a "strawberry tongue". The skin on his hands and feet is peeling. Diagnosis?', '["Scarlet fever", "Kawasaki disease", "Toxic Shock Syndrome", "Staph Scalded Skin Syndrome"]', 1, 'Desquamation is a late sign of Kawasaki. (Nelson)'),
    (v_topic_id, '214: What is the most common cause of bronchiolitis in children?', '["Adenovirus", "RSV", "Influenza", "Parainfluenza"]', 1, 'RSV is the most frequent cause. (Nelson)'),
    (v_topic_id, '215: What is the management for an infant with RSV bronchiolitis and mild respiratory distress?', '["Nebulized Albuterol", "Nebulized Epinephrine", "Supportive care (suction, hydration)", "Oral steroids"]', 2, 'Mainstay of treatment for bronchiolitis is supportive care. (AAP)'),
    (v_topic_id, '216: A child presents with fever, headache, and a petechial rash. You suspect meningococcemia. What is the most important immediate step?', '["Head CT", "Blood cultures and immediate IV antibiotics", "Lumbar puncture", "Wait for rash to progress"]', 1, 'Meningococcemia is a life-threatening emergency; do not delay antibiotics. (Case Files)'),
    (v_topic_id, '217: What is the most common bacterial cause of pediatric pneumonia?', '["Mycoplasma", "S. pneumoniae", "S. aureus", "H. influenzae"]', 1, 'S. pneumoniae is the most common bacterial cause overall. (Nelson)'),
    (v_topic_id, '218: A child presents with an itchy, "honey-colored" crusty lesion. Treatment?', '["Oral amoxicillin", "Topical mupirocin", "Oral acyclovir", "Topical steroids"]', 1, 'Mupirocin is effective for localized impetigo. (Harriet Lane)'),
    (v_topic_id, '219: A child presents with multiple umbilicated papules. Causative agent?', '["Poxvirus", "HPV", "HSV", "HHV-6"]', 0, 'Molluscum contagiosum is caused by a poxvirus. (Nelson)'),
    (v_topic_id, '220: A child presents with a "Christmas tree" distribution of scaly lesions on the back. Diagnosis?', '["Pityriasis rosea", "Secondary syphilis", "Psoriasis", "Tinea corporis"]', 0, 'Classic description of pityriasis rosea. (Case Files)'),
    (v_topic_id, '221: A child presents with fever and a "slapped cheek" rash. What is the organism?', '["HHV-6", "Parvovirus B19", "Rubella virus", "Measles virus"]', 1, 'Parvovirus B19 causes Erythema Infectiosum. (Nelson)'),
    (v_topic_id, '222: High fever followed by a rash after the fever goes away is classic for:', '["Roseola", "Measles", "Rubella", "Varicella"]', 0, 'Roseola (Exanthema Subitum) is the only common rash that appears *after* the fever. (Harriet Lane)'),
    (v_topic_id, '223: A child presents with "dewdrops on a rose petal" lesions. When is the child no longer contagious?', '["When the fever stops", "When all lesions are crusted over", "When the rash starts", "When they feel better"]', 1, 'Varicella is contagious until all vesicles have crusted. (Nelson)'),
    (v_topic_id, '224: A child presents with a "steeplesign" on neck X-ray. Diagnosis?', '["Epiglottitis", "Croup", "Bacterial tracheitis", "Foreign body"]', 1, 'The steeple sign indicates subglottic narrowing in croup. (Case Files)'),
    (v_topic_id, '225: A child presents with a "thumbprint sign" on lateral neck X-ray. Diagnosis?', '["Croup", "Epiglottitis", "Retropharyngeal abscess", "Peritonsillar abscess"]', 1, 'The thumbprint sign indicates a swollen epiglottis. (Nelson)'),
    (v_topic_id, '226: A child presents with painful, grouped vesicles on the lips. Diagnosis?', '["Impetigo", "Herpes Labialis", "Aphthous ulcer", "Hand-foot-mouth disease"]', 1, 'Recurrent HSV-1 infection (cold sores). (Harriet Lane)'),
    (v_topic_id, '227: A child presents with fever, sore throat, and a diffuse maculopapular rash after taking amoxicillin. Diagnosis?', '["Penicillin allergy", "Infectious Mononucleosis (EBV)", "Scarlet fever", "Measles"]', 1, 'Amoxicillin often triggers a rash in the presence of EBV infection. (Case Files)'),
    (v_topic_id, '228: A child has a red, itchy scalp with tiny white eggs attached to the hair shafts. Diagnosis?', '["Tinea capitis", "Pediculosis capitis (Lice)", "Seborrhea", "Psoriasis"]', 1, 'Head lice nits are firmly attached to the hair. (Nelson)'),
    (v_topic_id, '229: A child presents with "pinworm" infection. What is the most common symptom?', '["Abdominal pain", "Nighttime perianal itching", "Diarrhea", "Weight loss"]', 1, 'Enterobius vermicularis causes nocturnal pruritus. (Harriet Lane)'),
    (v_topic_id, '230: What is the most common cause of viral gastroenteritis in children?', '["Rotavirus", "Norovirus", "Adenovirus", "Giardia"]', 0, 'Rotavirus is the leading cause of severe diarrhea in children worldwide. (Nelson)'),
    (v_topic_id, '231: A child presents with bloody diarrhea and abdominal pain. He recently ate undercooked chicken. Organism?', '["Salmonella", "Campylobacter", "Shigella", "E. coli"]', 1, 'Campylobacter is often associated with poultry. (Case Files)'),
    (v_topic_id, '232: A child presents with fever and back pain. Disc space narrowing is seen on X-ray. Diagnosis?', '["Osteomyelitis", "Discitis", "Scoliosis", "Spondylolisthesis"]', 1, 'Discitis is an inflammation/infection of the intervertebral disc. (Nelson)'),
    (v_topic_id, '233: A 4-year-old child presents with fever, limping, and a "septic" looking hip joint. Next step?', '["Ibuprofen and follow-up", "Urgent orthopedic consultation for drainage", "X-ray and wait", "Oral antibiotics"]', 1, 'Septic arthritis requires immediate drainage to prevent joint damage. (Harriet Lane)'),
    (v_topic_id, '234: What is the most common organism in a child with septic arthritis?', '["GBS", "Staphylococcus aureus", "Kingella kingae", "S. pneumoniae"]', 1, 'S. aureus is the most frequent cause overall. (Nelson)'),
    (v_topic_id, '235: A child with sickle cell disease has osteomyelitis. Which organism is particularly common in this population?', '["S. aureus", "Salmonella", "Pseudomonas", "Listeria"]', 1, 'Salmonella is a classic pathogen in sickle cell patients with bone infection. (Case Files)'),
    (v_topic_id, '236: A child presents with a "bulls-eye" rash. What is the organism?', '["Borrelia burgdorferi", "Rickettsia rickettsii", "Treponema pallidum", "Francisella tularensis"]', 0, 'Lyme disease is caused by Borrelia burgdorferi. (Nelson)'),
    (v_topic_id, '237: What is the most common cause of neonatal sepsis?', '["Group B Strep (GBS)", "E. coli", "Listeria", "Staph aureus"]', 0, 'GBS is the leading cause in the first week of life. (Harriet Lane)'),
    (v_topic_id, '238: A neonate has jaundice, microcephaly, and periventricular calcifications. Organism?', '["Toxoplasmosis", "CMV", "Rubella", "Herpes"]', 1, 'Congenital CMV classically features periventricular calcifications. (Case Files)'),
    (v_topic_id, '239: A child presents with a "slapped cheek" rash. Which virus causes this?', '["HHV-6", "Parvovirus B19", "RSV", "Adenovirus"]', 1, 'Parvovirus B19 is the cause of Erythema Infectiosum. (Nelson)'),
    (v_topic_id, '240: What is the treatment for a 10-year-old child with early Lyme disease?', '["Amoxicillin", "Doxycycline", "Azithromycin", "Ceftriaxone"]', 1, 'Doxycycline is preferred for children >8 years old. (AAP)'),
    (v_topic_id, '241: A child presents with high fever and a "strawberry tongue". What is the first-line treatment for Scarlet Fever?', '["Penicillin V", "Azithromycin", "Ciprofloxacin", "Doxycycline"]', 0, 'Penicillin remains the gold standard for Group A Strep pharyngitis and scarlet fever. (Nelson)'),
    (v_topic_id, '242: What is the most common cause of neonatal sepsis in the United States?', '["Group B Streptococcus", "E. coli", "Listeria monocytogenes", "Staph aureus"]', 0, 'GBS is the most common organism. (Harriet Lane)'),
    (v_topic_id, '243: A child presents with a high fever and a "barking" cough. Which of the following is most likely to reduce the need for hospitalization?', '["A single dose of Dexamethasone", "Daily Albuterol", "A 5-day course of Amoxicillin", "Cough suppressants"]', 0, 'Steroids are highly effective at reducing airway inflammation in croup. (Case Files)'),
    (v_topic_id, '244: A child presents with a "thumbprint" sign on X-ray. What is the most likely diagnosis?', '["Croup", "Epiglottitis", "Retropharyngeal abscess", "Foreign body"]', 1, 'Thumbprint sign = Epiglottitis. (Nelson)'),
    (v_topic_id, '245: What is the most common cause of bronchiolitis in children?', '["RSV", "Adenovirus", "Influenza", "Parainfluenza"]', 0, 'RSV is the leading cause. (Nelson)'),
    (v_topic_id, '246: A 2-year-old child presents with a fever and a simple febrile seizure. What is the risk of developing epilepsy compared to the general population?', '["Significantly higher (10-20%)", "Slightly higher (~2-3% vs 1%)", "No different", "Lower"]', 1, 'The risk is only slightly increased after a simple febrile seizure. (Nelson)'),
    (v_topic_id, '247: What is the classic triad of Infectious Mononucleosis?', '["Fever, Sore Throat, Lymphadenopathy", "Fever, Rash, Joint pain", "Cough, Coryza, Conjunctivitis", "Headache, Stiff neck, Photophobia"]', 0, 'This triad is seen in the majority of symptomatic cases. (Case Files)'),
    (v_topic_id, '248: A child presents with high fever, neck stiffness, and a petechial rash. You should suspect:', '["Meningococcemia", "Lyme disease", "Varicella", "Measles"]', 0, 'Meningococcemia is a classic cause of fever and petechiae. (Harriet Lane)'),
    (v_topic_id, '249: What is the most common organism causing osteomyelitis in children?', '["S. aureus", "Salmonella", "Group A Strep", "Pseudomonas"]', 0, 'S. aureus is the most common cause. (Nelson)'),
    (v_topic_id, '250: A child presents with a "slapped cheek" rash. What is the causative agent?', '["Parvovirus B19", "Human Herpesvirus 6", "Rubella", "Measles"]', 0, 'Parvovirus B19 causes Erythema Infectiosum. (Case Files)'),
    (v_topic_id, '251: A child presents with high fever for 4 days followed by a rash. Diagnosis?', '["Roseola", "Measles", "Rubella", "Varicella"]', 0, 'Roseola features fever followed by rash. (Nelson)'),
    (v_topic_id, '252: A child presents with "dewdrops on a rose petal". Diagnosis?', '["Varicella", "Measles", "Smallpox", "Impetigo"]', 0, 'Classic description of chickenpox. (Harriet Lane)'),
    (v_topic_id, '253: A child presents with Koplik spots. Diagnosis?', '["Measles", "Mumps", "Rubella", "Scarlet fever"]', 0, 'Koplik spots are pathognomonic for measles. (Nelson)'),
    (v_topic_id, '254: A child presents with parotid swelling. Diagnosis?', '["Mumps", "Lymphadenitis", "Sialolithiasis", "Sarcoidosis"]', 0, 'Parotid swelling is the hallmark of mumps. (Case Files)'),
    (v_topic_id, '255: What is the most common cause of UTI in children?', '["E. coli", "Proteus", "Klebsiella", "Staph saprophyticus"]', 0, 'E. coli causes most UTIs. (Nelson)'),
    (v_topic_id, '256: A child presents with honey-colored crusts on the face. Diagnosis?', '["Impetigo", "Cellulitis", "Erysipelas", "Eczema"]', 0, 'Impetigo is classic for honey-colored crusts. (Harriet Lane)'),
    (v_topic_id, '257: What is the treatment for localized impetigo?', '["Topical Mupirocin", "Oral Amoxicillin", "Topical Steroids", "Oral Acyclovir"]', 0, 'Topical antibiotics are sufficient for limited lesions. (Nelson)'),
    (v_topic_id, '258: A child presents with a barking cough. Diagnosis?', '["Croup", "Epiglottitis", "Bronchiolitis", "Asthma"]', 0, 'Barking cough is characteristic of croup. (Case Files)'),
    (v_topic_id, '259: What is the most common cause of viral meningitis in children?', '["Enteroviruses", "HSV", "Mumps", "Voster"]', 0, 'Enteroviruses are the leading cause. (Nelson)'),
    (v_topic_id, '260: A child presents with fever and a bulging fontanelle. Diagnosis?', '["Meningitis", "Encephalitis", "Hydrocephalus", "Normal finding"]', 0, 'Bulging fontanelle is a sign of increased intracranial pressure, often from meningitis. (Harriet Lane)'),
    (v_topic_id, '261: A child presents with a "staccato" cough. Organism?', '["Chlamydia trachomatis", "Pertussis", "RSV", "Mycoplasma"]', 0, 'Chlamydia pneumonia in infants features a staccato cough. (Case Files)'),
    (v_topic_id, '262: A child presents with fever and a "strawberry tongue". Diagnosis?', '["Scarlet Fever or Kawasaki Disease", "Measles", "Rubella", "Mononucleosis"]', 0, 'Both can present with a strawberry tongue. (Nelson)'),
    (v_topic_id, '263: What is the most common organism in a child with a boil (furuncle)?', '["Staphylococcus aureus", "Streptococcus pyogenes", "E. coli", "Pseudomonas"]', 0, 'S. aureus is the most common cause of skin abscesses. (Harriet Lane)'),
    (v_topic_id, '264: A child presents with a "Christmas tree" rash. Diagnosis?', '["Pityriasis rosea", "Psoriasis", "Syphilis", "Tinea"]', 0, 'Christmas tree distribution is classic for pityriasis rosea. (Nelson)'),
    (v_topic_id, '265: A child presents with "slapped cheek" rash. Organism?', '["Parvovirus B19", "HHV-6", "HHV-7", "Rubella"]', 0, 'Parvovirus B19 causes Fifth disease. (Case Files)'),
    (v_topic_id, '266: What is the treatment for tinea capitis?', '["Oral Griseofulvin", "Topical Ketoconazole", "Oral Amoxicillin", "Topical Steroids"]', 0, 'Oral antifungal treatment is required for scalp infections. (Nelson)'),
    (v_topic_id, '267: A child presents with a "herald patch". Diagnosis?', '["Pityriasis rosea", "Tinea corporis", "Lyme disease", "Nummular eczema"]', 0, 'Herald patch precedes the main rash in pityriasis rosea. (Harriet Lane)'),
    (v_topic_id, '268: What is the most common cause of fungal diaper rash?', '["Candida albicans", "Trichophyton", "Malassezia", "Aspergillus"]', 0, 'Candida is the leading cause of fungal diaper dermatitis. (Case Files)'),
    (v_topic_id, '269: A child presents with a "bulls-eye" rash. Treatment?', '["Amoxicillin (if <8)", "Azithromycin", "Ceftriaxone", "Vancomycin"]', 0, 'Amoxicillin is preferred for early Lyme in young children. (Nelson)'),
    (v_topic_id, '270: A child presents with fever and a new murmur. Suspicion?', '["Infective Endocarditis", "Rheumatic Fever", "Both A and B", "Neither"]', 2, 'Both can cause new murmurs and fever. (Harriet Lane)'),
    (v_topic_id, '271: What is the Jones criteria used to diagnose?', '["Acute Rheumatic Fever", "Kawasaki Disease", "Endocarditis", "Lupus"]', 0, 'Jones criteria are for ARF. (Nelson)'),
    (v_topic_id, '272: A child presents with migratory polyarthritis. This is a major criterion for:', '["Acute Rheumatic Fever", "JIA", "Lyme disease", "Septic arthritis"]', 0, 'Migratory polyarthritis is a classic sign of ARF. (Case Files)'),
    (v_topic_id, '273: What is the most common cause of viral gastroenteritis in children?', '["Rotavirus", "Norovirus", "Sapovirus", "Adenovirus"]', 0, 'Rotavirus is very common in young children. (Nelson)'),
    (v_topic_id, '274: A child presents with watery diarrhea and vomiting. Best initial treatment?', '["Oral Rehydration Therapy", "IV Fluids", "Antidiarrheals", "Antibiotics"]', 0, 'ORT is preferred for most cases. (Harriet Lane)'),
    (v_topic_id, '275: A child presents with bloody diarrhea after eating undercooked meat. Suspect:', '["E. coli O157:H7", "Rotavirus", "Norovirus", "Giardia"]', 0, 'EHEC is associated with undercooked ground beef. (Case Files)'),
    (v_topic_id, '276: What is the triad of HUS?', '["Anemia, Thrombocytopenia, Renal Failure", "Fever, Rash, Joint pain", "Cough, Coryza, Conjunctivitis", "None"]', 0, 'Hemolytic Uremic Syndrome features these three findings. (Nelson)'),
    (v_topic_id, '277: A child presents with "breakbone fever". Diagnosis?', '["Dengue Fever", "Malaria", "Typhoid", "Chikungunya"]', 0, 'Dengue is known for severe joint/muscle pain. (Harriet Lane)'),
    (v_topic_id, '278: What is the most common cause of neonatal meningitis?', '["Group B Strep", "Listeria", "E. coli", "All are common"]', 3, 'These are the three big neonatal pathogens. (Nelson)'),
    (v_topic_id, '279: A child presents with fever and a bulging fontanelle. Next step?', '["Lumbar Puncture", "Head CT", "Observation", "Aspirin"]', 0, 'LP is needed to diagnose meningitis. (Case Files)'),
    (v_topic_id, '280: What is the treatment for suspected bacterial meningitis?', '["IV Vancomycin and Ceftriaxone", "Oral Amoxicillin", "Oral Acyclovir", "None"]', 0, 'Broad-spectrum IV antibiotics are needed urgently. (Harriet Lane)'),
    (v_topic_id, '281: A child presents with "Hand-Foot-and-Mouth disease". Virus?', '["Coxsackievirus", "Herpes virus", "Parvovirus", "Adenovirus"]', 0, 'Coxsackie A16 is a common cause. (Nelson)'),
    (v_topic_id, '282: A child presents with fever and "cold sores". Virus?', '["HSV-1", "HSV-2", "VZV", "EBV"]', 0, 'HSV-1 is the most common cause of oral herpes. (Case Files)'),
    (v_topic_id, '283: A child presents with a sore throat and a gray membrane. Suspect:', '["Diphtheria", "Mononucleosis", "Strep throat", "Candidiasis"]', 0, 'Pseudomembrane is characteristic of diphtheria. (Nelson)'),
    (v_topic_id, '284: A child presents with "swimmer''s ear". Treatment?', '["Topical Antibiotic drops", "Oral Amoxicillin", "Systemic steroids", "Warm oil"]', 0, 'Topical drops are usually sufficient. (Harriet Lane)'),
    (v_topic_id, '285: A child has fluid in the ear but no pain or fever. Diagnosis?', '["Otitis media with effusion", "Acute otitis media", "Otitis externa", "Normal ear"]', 0, 'OME is fluid without acute infection. (Case Files)'),
    (v_topic_id, '286: A child presents with a "staccato" cough. Suspect:', '["Chlamydia", "Pertussis", "RSV", "Mycoplasma"]', 0, 'Classic description for Chlamydia pneumonia in infants. (Nelson)'),
    (v_topic_id, '287: A child presents with "walking pneumonia". Treatment?', '["Azithromycin", "Amoxicillin", "Ceftriaxone", "Vancomycin"]', 0, 'Macrolides are used for Mycoplasma. (Harriet Lane)'),
    (v_topic_id, '288: What is the most common cause of periorbital cellulitis?', '["Skin trauma or insect bite", "Sinusitis", "Dental infection", "Blood spread"]', 0, 'Preseptal (periorbital) is often from skin breaks; orbital is often from sinuses. (Case Files)'),
    (v_topic_id, '289: A child presents with a limp and fever. Suspect:', '["Septic arthritis", "Transient synovitis", "Both", "Neither"]', 2, 'Both are in the differential for an acute limp with fever. (Nelson)'),
    (v_topic_id, '290: What is the classic X-ray finding for croup?', '["Steeple sign", "Thumbprint sign", "Sail sign", "Boot heart"]', 0, 'Steeple sign indicates subglottic narrowing. (Harriet Lane)'),
    (v_topic_id, '291: A child presents with fever and parotid swelling. Complication to watch for?', '["Orchitis", "Pancreatitis", "Meningitis", "All of the above"]', 3, 'Mumps can cause all of these. (Nelson)'),
    (v_topic_id, '292: What is the treatment for head lice?', '["Topical Permethrin", "Oral Amoxicillin", "Topical Ketoconazole", "Shaving the head"]', 0, 'Permethrin is standard treatment. (Case Files)'),
    (v_topic_id, '293: A child presents with itchy "burrows" between the fingers. Diagnosis?', '["Scabies", "Lice", "Eczema", "Impetigo"]', 0, 'Scabies features linear burrows. (Nelson)'),
    (v_topic_id, '294: A child presents with umbilicated papules. Diagnosis?', '["Molluscum contagiosum", "Warts", "Varicella", "Acne"]', 0, 'Central umbilication is the key. (Harriet Lane)'),
    (v_topic_id, '295: A child has honey-colored crusts. Organism?', '["S. aureus or S. pyogenes", "HSV", "E. coli", "Pseudomonas"]', 0, 'These cause impetigo. (Case Files)'),
    (v_topic_id, '296: A child presents with "slapped cheek" rash. Can they go to school?', '["Yes, no longer contagious", "No, wait 1 week", "Yes, only with mask", "No, never"]', 0, 'The rash is immune-mediated and occurs after the viremic phase. (Nelson)'),
    (v_topic_id, '297: A child presents with high fever and "whooping" cough. Prevention?', '["Vaccination", "Antibiotics", "Handwashing", "Isolation"]', 0, 'Vaccination (DTaP/Tdap) is key. (Harriet Lane)'),
    (v_topic_id, '298: What is the most common cause of bronchiolitis?', '["RSV", "Adenovirus", "Influenza", "Parainfluenza"]', 0, 'RSV is #1. (Nelson)'),
    (v_topic_id, '299: A child presents with fever and strawberry tongue. Diagnosis?', '["Kawasaki or Scarlet Fever", "Measles", "Rubella", "Mumps"]', 0, 'Both are classic for strawberry tongue. (Case Files)'),
    (v_topic_id, '300: A child presents with high fever for 4 days then a rash. Diagnosis?', '["Roseola", "Measles", "Rubella", "Varicella"]', 0, 'Fever then rash = Roseola. (Harriet Lane)');
